import json, glob
def rows(name):
    out = []
    for p in [f'state/{name}.jsonl'] + sorted(glob.glob(f'state/{name}.d/*.jsonl')):
        for line in open(p, encoding='utf-8'):
            if line.strip():
                out.append(json.loads(line))
    return out
